        fun addHASQUALITY(builder: FlatBufferBuilder, hasQuality: Boolean) = builder.addBoolean(38, hasQuality, false)
        fun addPROCESSING(builder: FlatBufferBuilder, processing: Int) = builder.addOffset(39, processing, 0)
        fun addPROVENANCE(builder: FlatBufferBuilder, provenance: Int) = builder.addOffset(40, provenance, 0)
        fun addSOURCECID(builder: FlatBufferBuilder, sourceCid: Int) = builder.addOffset(41, sourceCid, 0)
        fun addSOURCEDIGEST(builder: FlatBufferBuilder, sourceDigest: Int) = builder.addOffset(42, sourceDigest, 0)
        fun addRETRIEVEDAT(builder: FlatBufferBuilder, retrievedAt: Int) = builder.addOffset(43, retrievedAt, 0)
        fun endSDI(builder: FlatBufferBuilder) : Int {
            val o = builder.endTable()
                builder.required(o, 16)
                builder.required(o, 84)
            return o
        }
        fun finishSDIBuffer(builder: FlatBufferBuilder, offset: Int) = builder.finish(offset, "$SDI")
        fun finishSizePrefixedSDIBuffer(builder: FlatBufferBuilder, offset: Int) = builder.finishSizePrefixed(offset, "$SDI")
    }
}
